CREATE TABLE IF NOT EXISTS construction_intelligence.market_rate_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rate_date date NOT NULL, item_key varchar(30) NOT NULL, rate numeric(12,2) NOT NULL, unit varchar(10) NOT NULL, source varchar(20) NOT NULL DEFAULT 'WHATSAPP', source_ref uuid, status varchar(12) NOT NULL DEFAULT 'ACTIVE', supersedes_id uuid, record_type varchar(10) NOT NULL DEFAULT 'FACT', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_market_rate_item_date ON construction_intelligence.market_rate_quotes (item_key, rate_date);
